def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [i for i, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]
    # The panel background is the most frequent non-divider color; the sparse
    # contrasting color is the marker.
    counts = {}
    for r in range(h):
        if r in sep_rows:
            continue
        for c in range(w):
            if c in sep_cols:
                continue
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    marker = min((v for v in counts if v != background), key=counts.get)
    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    out = []
    for ri in range(len(rb)-1):
        row = []
        for ci in range(len(cb)-1):
            n = sum(grid[r][c] == marker
                    for r in range(rb[ri]+1, rb[ri+1])
                    for c in range(cb[ci]+1, cb[ci+1]))
            row.append(1 if n >= 2 else background)
        out.append(row)
    return out
